<?php require '_layout.php';$pdo=db();$edit=isset($_GET['id']);$m=['id'=>'','name'=>'','code'=>'','coefficient'=>'1.00','notes'=>'','image'=>''];$colors=[];if($edit&&$pdo){$q=$pdo->prepare('SELECT * FROM materials WHERE id=?');$q->execute([(int)$_GET['id']]);$m=$q->fetch(PDO::FETCH_ASSOC)?:$m;$q=$pdo->prepare('SELECT * FROM material_colors WHERE material_id=? ORDER BY id DESC');$q->execute([$m['id']]);$colors=$q->fetchAll(PDO::FETCH_ASSOC);}admin_header($edit?'Chỉnh sửa chất liệu':'Thêm chất liệu','materials');?><section class="form-page"><div class="form-heading"><div><a class="back" href="materials.php"><i class="bi bi-arrow-left"></i> Quay lại chất liệu</a><h2><?=$edit?'Chỉnh sửa':'Thêm mới'?> chất liệu</h2><p>Ảnh và hệ số dùng làm dữ liệu chuẩn cho cấu hình sản phẩm.</p></div></div><form class="product-form" method="post" action="material-save.php" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$m['id']?>"><div class="form-main"><section class="form-card"><h3>Thông tin cơ bản</h3><div class="field"><label>Tên *</label><input required name="name" value="<?=htmlspecialchars($m['name'])?>"></div><div class="field"><label>Mã *</label><input required pattern="[a-z0-9-]+" name="code" value="<?=htmlspecialchars($m['code'])?>"></div><div class="field"><label>Ghi chú</label><textarea name="notes" rows="5"><?=htmlspecialchars($m['notes'])?></textarea></div></section></div><aside class="form-side"><section class="form-card media-card"><h3>Ảnh chất liệu</h3><div class="field"><label>Upload ảnh</label><input accept="image/jpeg,image/png,image/webp" type="file" name="image"></div><?php if($m['image']):?><img class="image-preview" src="<?=htmlspecialchars($m['image'])?>" alt=""><?php endif?></section><section class="form-card"><h3>Hệ số</h3><div class="field"><label>Hệ số giá *</label><input required min="0" step="0.01" type="number" name="coefficient" value="<?=$m['coefficient']?>"></div></section><button class="admin-button save"><?=$edit?'Lưu thay đổi':'Tạo chất liệu'?></button><a class="cancel" href="materials.php">Huỷ</a></aside></form><?php if($edit):?><section class="colors-panel"><div class="panel-head"><div><div class="kicker">Bảng màu</div><h3>Màu của <?=htmlspecialchars($m['name'])?></h3></div><a class="admin-button" href="material-color-form.php?material_id=<?=$m['id']?>"><i class="bi bi-plus-lg"></i> Thêm màu</a></div><?php if(!$colors):?><div class="empty small"><i class="bi bi-palette"></i><p>Chưa có màu nào.</p></div><?php else:?><div class="color-table"><div><span>Ảnh</span><span>Mã</span><span>HEX</span><span></span></div><?php foreach($colors as $color):?><article><img src="<?=htmlspecialchars($color['image'])?>" alt=""><code><?=htmlspecialchars($color['code'])?></code><span><i class="hex-dot" style="background:<?=$color['hex_code']?>"></i><?=htmlspecialchars($color['hex_code'])?></span><div class="table-actions"><a href="material-color-form.php?material_id=<?=$m['id']?>&id=<?=$color['id']?>">Sửa</a><form method="post" action="material-color-delete.php"><input type="hidden" name="id" value="<?=$color['id']?>"><input type="hidden" name="material_id" value="<?=$m['id']?>"><button>Xoá</button></form></div></article><?php endforeach?></div><?php endif?></section><?php endif?></section><?php admin_footer(); ?>
